let cur = 'uk';
export function setLang(l) { cur = S[l] ? l : 'en'; document.documentElement.lang = cur; document.documentElement.dir = RTL.has(cur) ? 'rtl' : 'ltr'; }
export function getLang() { return cur; }
export function detectLang() {
  for (const l of navigator.languages || [navigator.language]) { const c = (l || '').slice(0, 2).toLowerCase(); if (S[c]) return c; }
  return 'en';
}
export function t(key, vars) {
  let s = (S[cur] && S[cur][key]) ?? S.en[key] ?? key;
  if (vars) for (const k in vars) s = s.replaceAll(`{${k}}`, vars[k]);
  return s;
}
export const ut = (n, unit) => unitText(cur, n, unit);
export const uw = (n, unit) => unitWord(cur, n, unit);
export function fmtDate(d, opts = { day: 'numeric', month: 'long', year: 'numeric' }) {
  return new Intl.DateTimeFormat(cur === 'zh' ? 'zh-CN' : cur, opts).format(new Date(d));
}
